const a = $input.first().json.body;
if (!Array.isArray(a)) throw Error("Invalid top stories");
return a.slice(0, 30).map((id) => ({ json: { id } }));

const u = $json.url;
return {
  json: {
    ...$json,
    match: typeof u === "string" && /^https:\/\/github\.com(?::443)?(?:[\/?#]|$)/i.test(u),
  },
};

const r = $json.output,
  u = $("Filter GitHub").item.json.url;
if (
  !r ||
  typeof r.twitter !== "string" ||
  [...r.twitter].length > 280 ||
  !r.twitter.includes(u) ||
  typeof r.linkedin !== "string" ||
  !r.linkedin.includes(u)
)
  throw Error("Invalid posts");
return { json: r };

const found = $("Find story").item.json;
const row = found.id ? found : $("Create Item").item.json;
if (!row.id || !row.Tweet || !row.LinkedIn) throw Error("Saved story lacks posts");
return { json: row };

if (!($json.id || $json.urn || $json.data?.id || $json.message_id || $json.result?.message_id))
  throw Error("Unknown write result; inspect service before retry");
return { json: $json };

